ADAPTER_OF = {"leitor:a12": "v10", "leitor:a13": "v11", "leitor:a14": "v12", "leitor:a15": "v13", "leitor:a16": "v14"}


def write_report(rows, n=1):
    R = FROUNDS[n]
    proposer = R.get("proposer", (PROPOSER,))[0]
    L = [f"# FÁBRICA DE REGRAS — ronda {n} (DECISIONS {R['decision']})", "",
         f"Gerado por tools/rule_factory.py ({VERSION}). " + INTRO[n][0].format(date=DATE) + f" Propõe {proposer} "
         f"(AMALIA + adaptador {ADAPTER_OF.get(proposer, 'v7')}), leitor:b revê às cegas; só fica settled a leitura que leitor:b replica "
         + ("com o mesmo conteúdo e a passagem-alvo citada (D64)." if R.get("content") else "em forma canónica (D43)."), "",
         INTRO[n][1], "",
         "| regra | passagem | estado | exato | direção | lacunas do vocabulário |", "|---|---|---|---|---|---|"]
    for r in rows:
        note = (f" ({r['why']})" if r.get("why") else "") + (f" ({r['rules']} regras)" if r.get("rules") else "")
        L.append(f"| {r['rule']} | {r['source']} | {r['state']}{note} | "
                 f"{'—' if r['exact'] is None else ('sim' if r['exact'] else 'não')} | {'—' if r['direction'] is None else ('sim' if r['direction'] else 'não')} | {'; '.join(r['gaps']) or '—'} |")
    L.append("")
    for r in rows:
        L += [f"## {r['rule']}", "", f"- {proposer}: {rr.show(r['a'])}", f"- leitor:b: {rr.show(r['b'])}", ""]
    (R["dir"] / f"FABRICA{n}.md").write_text("\n".join(L).replace("\n\n\n", "\n\n") + "\n", encoding="utf-8")


def main():
    ap = argparse.ArgumentParser(); ap.add_argument("cmd", choices=["targets", "prompts", "record", "recheck", "withdraw"]); ap.add_argument("--round", type=int, default=1, choices=sorted(FROUNDS))
    ap.add_argument("--rule"); ap.add_argument("--product-rule")
    a = ap.parse_args()
    if a.cmd in ("record", "recheck", "withdraw"):
        tool_is_current()
    if a.cmd == "withdraw":
        return cmd_withdraw(a.rule, a.product_rule)
    store = Store([ROOT / "law", ROOT / "rules", ROOT / "governance"]).load()
    if a.cmd == "targets":
        for t in targets(store, a.round):
            print(t["type"], t["source_passage"], len(t["candidates"]), t["rule"])
        return
    if a.cmd == "prompts":
        return cmd_prompts(store, a.round)
    if a.cmd == "recheck":
        return cmd_recheck(a.round)
    cmd_record(a.round)


if __name__ == "__main__":
    main()
